light.cssText:
.pattern-background {
position: relative;
overflow: hidden;
background-color: #452632;

}

.pattern-background::before {
content: "";
position: absolute;
inset: -100%;
transform: rotate(160deg);
transform-origin: center;
background-color: #452632;
opacity: 0.7;
background-image:  radial-gradient(#91204d 17%, #452632 18% 35%, transparent 36.5%), radial-gradient(#91204d 17%, #452632 18% 35%, transparent 36.5%), radial-gradient(#452632 34%, #91204d 36% 68%, transparent 70%), repeating-linear-gradient(45deg, #91204d -12.5% 12.5%, #452632 0 37.5%);
background-position: -30px -30px, 30px 30px, 0 0, 0 0;
background-size: 120px 120px, 120px 120px, 60px 60px, 120px 120px;
}

dark.cssText:
background-color: #e94e77;
opacity: 0.8;
background-image: radial-gradient(circle at center center, #d68189, #e94e77), repeating-radial-gradient(circle at center center, #d68189, #d68189, 15px, transparent 30px, transparent 15px);
background-blend-mode: multiply;

